def test_eager_wraps_variables_generator_returning_list():
    # Test that eager() wraps a VariablesGenerator callable and returns a List type wrapper
    # The eager decorator should convert any iterable-returning function into a list-returning function

    # Setup: Create a VariablesGenerator instance to be wrapped by eager
    variables_generator = module_1.VariablesGenerator()

    # Execute: Apply the eager decorator to the VariablesGenerator instance
    eager_wrapped_generator = module_1.eager(variables_generator)

    # Assert: Verify that the eager wrapper is callable and has been successfully created
    assert callable(eager_wrapped_generator), (
        "eager() should return a callable that wraps the original VariablesGenerator"
    )

def test_eager_wraps_callable_and_supports_debug_warn_get_source():
    """
    Test that the `eager` function correctly wraps a callable (including an integer-wrapped callable),
    and that `debug`, `warn`, and `get_source` can be called on these wrapped functions
    without raising errors.
    """
    # Constants
    INITIAL_VALUE = 939

    # Setup: Create an eager-wrapped callable from an integer value
    eager_wrapped_callable = module_1.eager(INITIAL_VALUE)

    # Setup: Create a VariablesGenerator instance (verifying instantiation works alongside these calls)
    variables_generator = module_1.VariablesGenerator()

    # Execution: Call debug with the eager-wrapped callable as the message provider
    debug_result = module_1.debug(eager_wrapped_callable)

    # Execution: Wrap the already-eager callable again with eager
    double_eager_wrapped_callable = module_1.eager(eager_wrapped_callable)

    # Execution: Call warn with the initial integer value as the message
    warn_result = module_1.warn(INITIAL_VALUE)

    # Execution & Assertion: Retrieve source code of the eager-wrapped callable
    # Verifies that get_source can inspect the wrapped function without raising errors
    module_1.get_source(eager_wrapped_callable)

    # Assert: debug and warn return None as expected
    assert debug_result is None
    assert warn_result is None

