def test_eager_decorator_with_non_callable_argument():
    """
    Test that the eager decorator raises an error when called with a non-callable
    argument (integer) as the function to wrap, and then attempts to invoke
    the resulting wrapped function with itself as arguments and None as the module.
    """
    # Setup
    NON_CALLABLE_VALUE = 939
    MODULE_VALUE = None

    # Execution & Assertion
    # eager expects a callable, but receives an integer (939)
    # this should raise a TypeError when the wrapped function tries to call the integer
    eager_wrapped = module_1.eager(NON_CALLABLE_VALUE)

    with pytest.raises((TypeError, Exception)):
        # Attempt to call the wrapped result with itself as positional and keyword arguments
        eager_wrapped.__call__(eager_wrapped, eager_wrapped, module=MODULE_VALUE, start=eager_wrapped)

